THACK = wks("William Makepeace Thackeray", [
 dict(title="Vanity Fair: A Novel without a Hero", year="1848",
   gb="Sensation Novel, Realist Novel of Common Life, Serial and Monthly-Part Novel", tb=MET+", " + ECON + ", The woman question, married disability, and the New Woman",
   mb="Sensation Fiction and the Serial Plot, Chartism and the Condition-of-England Novel", comp=["1847", "1848"],
   form="Novel in monthly parts (20 numbers, 1847-48); one volume 1848",
   desc="Published in twenty monthly parts from January 1847 to July 1848, with Thackeray's own illustrations, and subtitled 'A Novel without a Hero': the great English novel of the 1810s-20s seen from the vantage of the 1840s, and the book that fixed the word 'snob' and the phrase 'vanity fair' in the language.",
   plot="The novel follows two schoolfellows from Miss Pinkerton's academy: Amelia Sedley, the sentimental and self-deceiving daughter of a rich City merchant, and Becky Sharp, the penniless governess who determines to make her fortune. Amelia marries George Osborne, who is killed at Waterloo, and later the faithful, self-sacrificing William Dobbin; Becky marries Rawdon Crawley, becomes the favourite of the jealous Miss Crawley, is received into the highest society and then ruined by her intrigue with Lord Steyne, and ends as a respectable pensioner of Jos Sedley. The Waterloo section, the Brussels chapters, and the final fair scenes are the novel's set pieces.",
   context="The Regency and the Napoleonic wars, the Battle of Waterloo, the City bankruptcy of 1815-16, the marriage market of the gentry, and the India service and the colonial fortune; the novel is also a satire on the 1840s readership that consumed it.",
   sig="Vanity Fair is the central English novel of social satire in the nineteenth century and the definitive portrait of the adventuress. Becky Sharp is the first great female anti-heroine in English fiction, and the novel's refusal of a moralising ending made it a permanent point of reference for the ironic novel from Meredith to Thackeray's modernist readers.",
   chars="Becky Sharp; Amelia Sedley; George Osborne; William Dobbin; Rawdon Crawley; Miss Crawley; Lord Steyne; Jos Sedley; Mr Sedley; Sir Pitt Crawley; Miss Briggs",
   canon="Major canon",
   struct="Panoramic third-person narrative in twenty monthly parts, with a narrator who comments from the vantage of 1848 on the events of 1813-30, and a 'before and after the curtain' frame."),
 dict(title="The History of Pendennis: His Fortunes and Misfortunes, His Friends and His Greatest Enemy", year="1850",
   gb="Novel of Development and the Growth Story, Serial and Monthly-Part Novel", tb="Education, the schools, and the cultivation of the self, " + ECON,
   mb="Sensation Fiction and the Serial Plot", comp=["1848", "1850"],
   form="Novel in monthly parts (24 numbers)",
   desc="Published in twenty-four monthly parts from November 1848 to December 1850, a semi-autobiographical Bildungsroman of a young gentleman of the 1830s-40s and the first of Thackeray's novels to be set in his own century.",
   plot="Arthur Pendennis, the son of a West Country doctor's widow, goes up to Oxbridge, gets into debt, is jilted in his first love for the actress Emily Fotheringay, and comes to London to read for the bar and to write for the press. His uncle Major Pendennis manages his social career and the family's fortune, and after a period of dissipation and a broken engagement to Blanche Amory, he marries his childhood friend Laura Bell and settles into the life of a country gentleman and a successful novelist.",
   context="The 1830s-40s: the Regency survivors who manage the young man's career, the press as a profession for gentlemen, the debts and bailiffs of the 'swell', and the literary market that Thackeray himself inhabited.",
   sig="Pendennis is the most directly autobiographical of Thackeray's novels and the fullest English account of the making of a gentleman and a professional writer in the 1840s; it established the 'novel of a young man's education' as a vehicle for social criticism that Dickens, Trollope and Meredith all used.",
   chars="Arthur Pendennis; Helen Pendennis; Major Pendennis; Laura Bell; Emily Fotheringay; Blanche Amory; George Warrington; Harry Foker; Dr Portman; Costigan",
   canon="Secondary canon"),
 dict(title="The History of Henry Esmond, Esq., a Colonel in the Service of Her Majesty Queen Anne. Written by Himself", year="1852",
   gb="Serial and Monthly-Part Novel, Novel of Development and the Growth Story", tb="The metropolis, the crowd, and the imperial capital, League, jingoism, and the literature of the metropole".replace("League","Empire"),
   mb="Sensation Fiction and the Serial Plot", comp=["1851", "1852"],
   form="Historical novel in the first person",
   desc="Published in three volumes in 1852 and set in the reign of Queen Anne (1702-14): Thackeray's masterly historical novel, written throughout in the idiom of the early eighteenth century, and the only one of his books to sustain a single voice from beginning to end.",
   plot="Henry Esmond, a foundling of the Castlewood family who believes himself to be illegitimate, serves as a soldier under Marlborough in Flanders and as a man of letters in London, falling in love with his cousin Beatrix, who prefers the young Pretender. He marries Rachel, Lady Castlewood, who is in fact the mother of the true heir and whom he has loved since boyhood, and they emigrate to Virginia, where the novel's frame places the aged Esmond and his descendants.",
   context="The War of the Spanish Succession and the campaigns of Queen Anne, the Jacobite succession crisis, the death of Anne and the Hanoverian accession of 1714, and the London of Addison, Steele and Swift.",
   sig="Henry Esmond is the finest historical novel of the eighteenth century written in the nineteenth, and its archaised first-person narration — Thackeray's most sustained experiment in style — has been a permanent model for the historical novel in the first person, from Scott's and Thackeray's heirs to the historical fiction of the twentieth century.",
   chars="Henry Esmond; Rachel, Lady Castlewood; Beatrix Esmond; Francis Esmond; the second Viscount Castlewood; Lord Mohun; the Duke of Hamilton; Swift; Steele; Addison; Colonel Esmond",
   canon="Major canon"),
 dict(title="The Newcomes: Memoirs of a Most Respectable Family", year="1855",
   gb="Realist Novel of Common Life, Serial and Monthly-Part Novel", tb="credit, speculation, and the joint-stock imagination, The woman question, married disability, and the New Woman, Leisure class, the idle rich, and the unearned income",
   mb="Sensation Fiction and the Serial Plot", comp=["1853", "1855"],
   form="Novel in monthly parts (24 numbers)",
   desc="Published in twenty-four monthly parts from October 1853 to August 1855, narrated by Arthur Pendennis, and the most encompassing of Thackeray's family chronicles: the history of the Newcome family from the Indian fortune of the 'Campaigner' to the ruin of the banker Barnes Newcome.",
   plot="Clive Newcome, an artist, loves his cousin Ethel Newcome, who is pressed by her family into the marriage market; the novel follows the family's fortunes through the colonial service, the City bank, the influence of the evangelical 'Bungay' faction and the collapse of the bank of Hobson Brothers. Clive marries Rosey Mackenzie and is widowed, and Ethel remains unmarried in a resolution that the narrator leaves deliberately unresolved.",
   context="The 1830s-50s: the City bank and its failure, the Anglo-Indian family, the marriage market of the upper middle class, and the evangelical philanthropy of the second generation.",
   sig="The Newcomes is Thackeray's most sympathetic book and the most complete picture of the Victorian family across three generations; its portrait of Ethel Newcome as a woman with no independent income and no independent will is one of the period's sharpest studies of the position of women, and its phrase 'the most respectable family' became a byword for respectable hypocrisy.",
   chars="Clive Newcome; Ethel Newcome; Colonel Thomas Newcome; Barnes Newcome; Sir Brian Newcome; Lady Ann Newcome; Rosey Mackenzie; Arthur Pendennis; the Campaigner; Fred Bayham"),
 dict(title="The Virginians: A Tale of the Last Century", year="1859",
   gb="Serial and Monthly-Part Novel, Novel of Development and the Growth Story", tb="Democracy, individualism, and the American experiment, The closing of the American frontier, Empire, jingoism, and the literature of the metropole",
   mb="Sensation Fiction and the Serial Plot", comp=["1857", "1859"],
   form="Historical novel in monthly parts (24 numbers)",
   desc="Published in twenty-four monthly parts from November 1857 to October 1859, the sequel to Henry Esmond and the first English novel to treat the American Revolution from the perspective of a Virginian family divided by it.",
   plot="Henry and George Warrington, grandsons of Henry Esmond, grow up in Virginia; the novel follows them to London, into the army, through the American War of Independence, the death of George at the hands of a British officer, and the ruin and restoration of the family estate at Castlewood. The novel's history is deliberately digressive and its plot subordinate to the panorama of the 1750s-70s.",
   context="The Seven Years' War, the American Revolution, the London of the 1750s and the literary world of Fielding and Johnson, and the Virginia plantation economy of the eighteenth century.",
   sig="The Virginians is the most substantial English novel of the American Revolution and the fullest picture in Victorian fiction of the transatlantic family; its treatment of the colonial gentleman's divided loyalty is a significant document in the nineteenth-century English imagination of America."),
 dict(title="The Book of Snobs", year="1848",
   gb="Review Essay and Quarterly Argument, Lecture and Popular Address", tb="Leisure class, the idle rich, and the unearned income, The metropolis, the crowd, and the imperial capital",
   mb="Arnold and the Criticism of Culture", form="Collected periodical essays (Punch, 1846-47)",
   desc="A series of sketches published in Punch in 1846-47 and collected in 1848: a taxonomy of English snobbery — the country snob, the city snob, the military snob, the clerical snob, the literary snob — written in the person of a satirical observer who includes himself among the objects of the analysis.",
   plot="The book has no narrative. It proceeds by category and example, with mock-learned definitions and illustrative anecdotes, and it closes with an account of 'the snob royal' and the observation that 'the world is a snobbish world'.",
   context="The 1840s, the decade of the railway and the new money, the club and the dinner party, and the Punch humour of Douglas Jerrold, Lemon and Thackeray himself.",
   sig="The Book of Snobs fixed the word 'snob' in its modern social sense and gave the nineteenth century its most serviceable word for the fear of social inferiority; it is the satirical key to all of Thackeray's fiction, and it anticipates the modern sociology of status."),
 dict(title="The Four Georges", year="1861",
   gb="Lecture and Popular Address, Review Essay and Quarterly Argument", tb="Leisure class, the idle rich, and the unearned income, Empire, jingoism, and the literature of the metropole",
   mb="Arnold and the Criticism of Culture", form="Lectures (delivered 1855-56; published 1860-61)",
   desc="Four lectures on the Hanoverian kings, delivered in the United States in 1855-56 and in Britain from 1856, and published in the Cornhill Magazine in 1860 and as a book in 1861: a satire on the House of Hanover that works by the accumulation of trivial detail and by the contrast between the king's private life and the public pageant.",
   plot="Each lecture follows one king — George I, George II, George III, George IV — from accession to death, with anecdotes of mistresses, debts, court ceremonial and the king's tastes, and with Thackeray's commentary on the time's literature and manners.",
   context="The Hanoverian succession and the Jacobite risings, the Regency of the future George IV, and the 1850s vogue for historical lecturing that Thackeray shared with Dickens.",
   sig="The Four Georges was the most discussed historical writing of its year, and it taught the Victorian lecture audience that history could be written as social comedy; its method descends to Lytton Strachey's Eminent Victorians and to the modern biographical essay.",
   status="complete"),
 dict(title="The English Humourists of the Eighteenth Century", year="1853",
   gb="Lecture and Popular Address, Review Essay and Quarterly Argument", tb="The machinery of print: the serial, the magazine, and the book trade, The metropolis, the crowd, and the imperial capital",
   mb="Arnold and the Criticism of Culture", form="Lectures (delivered 1851; published 1853)",
   desc="Six lectures on Swift, Congreve, Addison and Steele, Pope, Hogarth, Smollett, Fielding, Sterne and Goldsmith, delivered in 1851 and published in 1853: the Victorian century's most influential account of the English eighteenth century, and a manifesto for the comic-satirical tradition that Thackeray claimed as his own.",
   plot="Each lecture is a biographical and critical estimate, illustrated by quotation from the writer's work and by anecdote from the memoirs, with Thackeray's judgement delivered in a tone of affectionate irony.",
   context="The 1850s lecture circuit, the Mechanics' Institutes and the fashionable lecture, and the Victorian rediscovery of the eighteenth century that produced Macaulay's History and Thackeray's own historical novels.",
   sig="The English Humourists taught the Victorians how to read their own eighteenth century and fixed the canonical estimate of Swift and Fielding for a century; its blend of biography, quotation and moral judgement is the model for the modern critical lecture and the literary essay."),
 dict(title="The Rose and the Ring; or, The History of Prince Giglio and Prince Bulbo. A Fire-Side Pantomime for Great and Small Children", year="1855",
   gb="Children's Fantasy and the Dream-Region Tale, Nonsense Verse and the Parody of Rule", tb="Childhood, the child labourer, and the sentimental child, Art versus life, and the romance of the artist",
   mb="Aestheticism and the Decadent Decade", form="Children's fantasy (illustrated by the author)",
   desc="Published in December 1854 (title page 1855), written for the Christmas pantomime and for the children of the household: a burlesque fairy tale of two rival kingdoms, the magic rose and ring that make their bearers irresistible, and a cast of comic courtiers.",
   plot="Prince Giglio of Paflagonia and Prince Bulbo of Crim Tartary are both endowed with supernatural charms by the fairy Blackstick; their rivalry for the Princess Angelica, the interference of the wicked Countess Gruffanuff, and the eventual pairing of the true lovers produce a plot of transformations and reversals in which nobody is quite what they seem.",
   context="The Victorian pantomime and the Christmas gift book, the chapbook and fairy-tale revival of the 1840s-50s, and the new market for children's illustrated books that Thackeray, Dickens and Ruskin all entered.",
   sig="The Rose and the Ring is one of the two or three founding texts of Victorian children's fantasy and the direct precursor of the comic fairy tale from Thackeray to Nesbit and beyond; its subversive treatment of royal and parental authority is unusual for its decade and it remains one of the funniest children's books of the century."),
])

